// This file is a fixture for the test suite. It is the same kind of room as
// the Valve one, written in the older shape: five plain numbers instead of
// the two texture axes in brackets.
//
// One unit is one thirty-second of a metre.
{
"classname" "worldspawn"
// brush 0: the floor
{
( 256 -256 -16 ) ( 256 -256 0 ) ( 256 256 -16 ) floor_surface 0 0 0 1 1
( -256 -256 -16 ) ( -256 256 -16 ) ( -256 -256 0 ) floor_surface 0 0 0 1 1
( -256 256 -16 ) ( 256 256 -16 ) ( -256 256 0 ) floor_surface 0 0 0 1 1
( -256 -256 -16 ) ( -256 -256 0 ) ( 256 -256 -16 ) floor_surface 0 0 0 1 1
( -256 -256 0 ) ( -256 256 0 ) ( 256 -256 0 ) floor_surface 0 0 0 1 1
( -256 -256 -16 ) ( 256 -256 -16 ) ( -256 256 -16 ) floor_surface 0 0 0 1 1
}
}
{
"classname" "func_checkpoint_start"
"origin" "-384 0 32"
}
